import json, os, subprocess
from pathlib import Path

source=Path("/Users/steventran/do-again")
expected_head="b5c09ec117b4cc9a3cb752ad248631a32a0b08eb"

def run(args):
    return subprocess.run(args,cwd=source,text=True,capture_output=True,check=False,env={**os.environ,"PYTHONPATH":str(source/"src")})

head=run(["git","rev-parse","HEAD"]).stdout.strip()
if head!=expected_head:
    raise SystemExit(f"target main moved; refusing upgrade: {head}")

pre=run(["python3","-m","do_again.cli","upgrade",str(source)])
print("=== preflight ===")
print(pre.stdout)
print(pre.stderr)
if pre.returncode!=0:
    raise SystemExit("preflight command failed")
prej=json.loads(pre.stdout)
if prej.get("effective_blockers"):
    raise SystemExit("target not quiescent; no upgrade attempted: "+json.dumps(prej.get("effective_blockers")))

apply=run(["python3","-m","do_again.cli","upgrade",str(source),"--apply"])
print("=== apply ===")
print(apply.stdout)
print(apply.stderr)
print("apply_rc="+str(apply.returncode))
if apply.returncode!=0:
    raise SystemExit("guarded upgrade command failed")

value=json.loads(apply.stdout)
if not value.get("applied"):
    raise SystemExit("upgrade deferred; no unsafe retry: "+json.dumps(value.get("effective_blockers") or value.get("preflight",{}).get("blockers")))

verification=value.get("verification") or {}
if verification.get("hash_matches") is not True:
    raise SystemExit("post-upgrade runtime hash verification failed")
if not (verification.get("service") or {}).get("running"):
    raise SystemExit("target service did not return running")

print(json.dumps({
  "transaction_id":value.get("transaction_id"),
  "verification":verification,
},indent=2,sort_keys=True))
print("CROSS_PROJECT_SELF_RUNTIME_UPGRADE_ACCEPTANCE_OK")
